// CstBlockFromTerm is Java Gom's CstBlock.fromTerm(trm).
func CstBlockFromTerm(trm aterm.ATerm) CstBlock {
	return CstBlockFromTermConv(trm, aterm.IdConverter{})
}

// CstBlockFromTermConv is Java Gom's CstBlock.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func CstBlockFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) CstBlock {
	converted := conv.Convert(trm)
	var results []CstBlock
	if r, ok := fromTermHOSTBLOCKCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_MetaquoteCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_MatchConstructCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_OpConstructCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_OpArrayConstructCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_OpListConstructCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_TypetermConstructCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_MetaQuoteConstructCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_IncludeFileCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_IncludeConstructCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_GomConstructCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_BQTermToBlockCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_ReturnBQTermCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_StrategyConstructCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_AbstractBlockCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_UnamedBlockCstBlock(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a CstBlock", trm), IllegalArgument: true})
	}
	return results[0]
}

// CstBlockFromString is Java Gom's CstBlock.fromString(s).
func CstBlockFromString(s string) CstBlock { return CstBlockFromTerm(aterm.GetInstance().Parse(s)) }

// CstBlockFromStream is Java Gom's CstBlock.fromStream(stream) (an IOException is
// the error).
func CstBlockFromStream(stream io.Reader) (CstBlock, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return CstBlockFromTerm(at), nil
}

