// ConsCst_AndConstraint is Java Gom's ConsCst_AndConstraint.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "FL" first).
func ConsCst_AndConstraint(head CstConstraint, tail CstConstraint) CstConstraint {
	// FL: flattened list
	if head.IsEmptyCst_AndConstraint() {
		return tail
	}
	if head.IsConsCst_AndConstraint() {
		return ConsCst_AndConstraint(head.GetHeadCst_AndConstraint(), ConsCst_AndConstraint(head.GetTailCst_AndConstraint(), tail))
	}
	if !tail.IsConsCst_AndConstraint() && !tail.IsEmptyCst_AndConstraint() {
		return ConsCst_AndConstraint(head, ConsCst_AndConstraint(tail, EmptyCst_AndConstraint()))
	}
	return RealMakeConsCst_AndConstraint(head, tail)
}

