// by ConsCst_AndConstraint, through the construction hooks (Java's Cst_AndConstraint.fromArray).
func MakeCst_AndConstraint(args ...CstConstraint) CstConstraint {
	var l CstConstraint = EmptyCst_AndConstraint()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsCst_AndConstraint(args[i], l)
	}
	return l
}

