// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *Cst_AndConstraintCstConstraint) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []CstConstraint
	var cur CstConstraint = t
	for {
		c, ok := cur.(*Cst_AndConstraintCstConstraint)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*Cst_AndConstraintCstConstraint); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermCst_AndConstraintCstConstraint is Java Gom's Cst_AndConstraint.fromTerm: an application of Cst_AndConstraint, or a
// list (of ToATerm), of convertible elements.
func fromTermCst_AndConstraintCstConstraint(trm aterm.ATerm, conv aterm.ATermConverter) (res CstConstraint, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "Cst_AndConstraint" {
		elems := make([]CstConstraint, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = CstConstraintFromTermConv(a, conv)
		}
		return MakeCst_AndConstraint(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a Cst_AndConstraint (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []CstConstraint
		for !list.IsEmpty() {
			elems = append(elems, CstConstraintFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeCst_AndConstraint(elems...), true
	}
	return nil, false
}

