// ConsCst_OrConstraint is Java Gom's ConsCst_OrConstraint.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "FL" first).
func ConsCst_OrConstraint(head CstConstraint, tail CstConstraint) CstConstraint {
	// FL: flattened list
	if head.IsEmptyCst_OrConstraint() {
		return tail
	}
	if head.IsConsCst_OrConstraint() {
		return ConsCst_OrConstraint(head.GetHeadCst_OrConstraint(), ConsCst_OrConstraint(head.GetTailCst_OrConstraint(), tail))
	}
	if !tail.IsConsCst_OrConstraint() && !tail.IsEmptyCst_OrConstraint() {
		return ConsCst_OrConstraint(head, ConsCst_OrConstraint(tail, EmptyCst_OrConstraint()))
	}
	return RealMakeConsCst_OrConstraint(head, tail)
}

// MakeCst_OrConstraint builds the list of args as Tom's `Cst_OrConstraint(args…)` does: from EmptyCst_OrConstraint,
// by ConsCst_OrConstraint, through the construction hooks (Java's Cst_OrConstraint.fromArray).
func MakeCst_OrConstraint(args ...CstConstraint) CstConstraint {
	var l CstConstraint = EmptyCst_OrConstraint()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsCst_OrConstraint(args[i], l)
	}
	return l
}

// Cst_OrConstraintFromArray is Java Gom's Cst_OrConstraint.fromArray(array).
func Cst_OrConstraintFromArray(array []CstConstraint) CstConstraint {
	return MakeCst_OrConstraint(array...)
}

