// Length is Java's length(): the number of elements of the list (a
// tail that is not a Cst_OrConstraint list counts as one element).
func (t *Cst_OrConstraintCstConstraint) Length() int {
	res := 0
	var tl CstConstraint = t
	for {
		c, ok := tl.(*Cst_OrConstraintCstConstraint)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*Cst_OrConstraintCstConstraint); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a Cst_OrConstraint list.
func (t *Cst_OrConstraintCstConstraint) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur CstConstraint = t
	for {
		c, ok := cur.(*Cst_OrConstraintCstConstraint)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*Cst_OrConstraintCstConstraint); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsCst_OrConstraint
// (through the hooks).
func (t *Cst_OrConstraintCstConstraint) Reverse() CstConstraint {
	if t.empty {
		return t
	}
	var cur CstConstraint = t
	var rev CstConstraint = EmptyCst_OrConstraint()
	for {
		c, ok := cur.(*Cst_OrConstraintCstConstraint)
		if !ok || c.empty {
			break
		}
		rev = ConsCst_OrConstraint(c.head, rev)
		cur = c.tail
	}
	if c, ok := cur.(*Cst_OrConstraintCstConstraint); !ok || !c.empty {
		rev = ConsCst_OrConstraint(cur, rev)
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsCst_OrConstraint (through the hooks).
func (t *Cst_OrConstraintCstConstraint) Append(element CstConstraint) CstConstraint {
	var heads []CstConstraint
	var cur CstConstraint = t
	for {
		c, ok := cur.(*Cst_OrConstraintCstConstraint)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res CstConstraint
	if c, ok := cur.(*Cst_OrConstraintCstConstraint); ok && c.empty {
		res = ConsCst_OrConstraint(element, cur)
	} else {
		res = ConsCst_OrConstraint(cur, element)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsCst_OrConstraint(heads[i], res)
	}
	return res
}

func (t *Cst_OrConstraintCstConstraint) CompareTo(o any) int {
	for {
		ao := o.(CstConstraint)
		if ao == CstConstraint(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*Cst_OrConstraintCstConstraint)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*Cst_OrConstraintCstConstraint)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *Cst_OrConstraintCstConstraint) CompareToLPO(o any) int {
	for {
		ao := o.(CstConstraint)
		if ao == CstConstraint(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*Cst_OrConstraintCstConstraint)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*Cst_OrConstraintCstConstraint)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *Cst_OrConstraintCstConstraint) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []CstConstraint
	var cur CstConstraint = t
	for {
		c, ok := cur.(*Cst_OrConstraintCstConstraint)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*Cst_OrConstraintCstConstraint); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermCst_OrConstraintCstConstraint is Java Gom's Cst_OrConstraint.fromTerm: an application of Cst_OrConstraint, or a
// list (of ToATerm), of convertible elements.
func fromTermCst_OrConstraintCstConstraint(trm aterm.ATerm, conv aterm.ATermConverter) (res CstConstraint, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "Cst_OrConstraint" {
		elems := make([]CstConstraint, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = CstConstraintFromTermConv(a, conv)
		}
		return MakeCst_OrConstraint(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a Cst_OrConstraint (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []CstConstraint
		for !list.IsEmpty() {
			elems = append(elems, CstConstraintFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeCst_OrConstraint(elems...), true
	}
	return nil, false
}

