// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new CstConstraint[]{}): a last tail
// that is not a list (of sort CstConstraintList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcCstConstraintCstConstraintList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur CstConstraintList = t
	for {
		c, ok := cur.(*ConcCstConstraintCstConstraintList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcCstConstraintCstConstraintList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a ConcCstConstraint list is not a CstConstraint", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

