// Length is Java's length(): the number of elements of the list (a
// tail that is not a ConcCstConstraint list counts as one element).
func (t *ConcCstConstraintCstConstraintList) Length() int {
	res := 0
	var tl CstConstraintList = t
	for {
		c, ok := tl.(*ConcCstConstraintCstConstraintList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*ConcCstConstraintCstConstraintList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a ConcCstConstraint list.
func (t *ConcCstConstraintCstConstraintList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur CstConstraintList = t
	for {
		c, ok := cur.(*ConcCstConstraintCstConstraintList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*ConcCstConstraintCstConstraintList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsConcCstConstraint
// (through the hooks).
func (t *ConcCstConstraintCstConstraintList) Reverse() CstConstraintList {
	if t.empty {
		return t
	}
	var cur CstConstraintList = t
	var rev CstConstraintList = EmptyConcCstConstraint()
	for {
		c, ok := cur.(*ConcCstConstraintCstConstraintList)
		if !ok || c.empty {
			break
		}
		rev = ConsConcCstConstraint(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsConcCstConstraint (through the hooks).
func (t *ConcCstConstraintCstConstraintList) Append(element CstConstraint) CstConstraintList {
	var heads []CstConstraint
	var cur CstConstraintList = t
	for {
		c, ok := cur.(*ConcCstConstraintCstConstraintList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res CstConstraintList
	if c, ok := cur.(*ConcCstConstraintCstConstraintList); ok && c.empty {
		res = ConsConcCstConstraint(element, cur)
	} else {
		res = ConsConcCstConstraint(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcCstConstraint(heads[i], res)
	}
	return res
}

func (t *ConcCstConstraintCstConstraintList) CompareTo(o any) int {
	for {
		ao := o.(CstConstraintList)
		if ao == CstConstraintList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcCstConstraintCstConstraintList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcCstConstraintCstConstraintList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *ConcCstConstraintCstConstraintList) CompareToLPO(o any) int {
	for {
		ao := o.(CstConstraintList)
		if ao == CstConstraintList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcCstConstraintCstConstraintList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcCstConstraintCstConstraintList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcCstConstraintCstConstraintList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []CstConstraint
	var cur CstConstraintList = t
	for {
		c, ok := cur.(*ConcCstConstraintCstConstraintList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcCstConstraintCstConstraintList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcCstConstraintCstConstraintList is Java Gom's ConcCstConstraint.fromTerm: an application of ConcCstConstraint, or a
// list (of ToATerm), of convertible elements.
func fromTermConcCstConstraintCstConstraintList(trm aterm.ATerm, conv aterm.ATermConverter) (res CstConstraintList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "ConcCstConstraint" {
		elems := make([]CstConstraint, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = CstConstraintFromTermConv(a, conv)
		}
		return MakeConcCstConstraint(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a ConcCstConstraint (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []CstConstraint
		for !list.IsEmpty() {
			elems = append(elems, CstConstraintFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcCstConstraint(elems...), true
	}
	return nil, false
}

