// CstTermFromTerm is Java Gom's CstTerm.fromTerm(trm).
func CstTermFromTerm(trm aterm.ATerm) CstTerm { return CstTermFromTermConv(trm, aterm.IdConverter{}) }

// CstTermFromTermConv is Java Gom's CstTerm.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func CstTermFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) CstTerm {
	converted := conv.Convert(trm)
	var results []CstTerm
	if r, ok := fromTermCst_TermVariableCstTerm(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_TermVariableStarCstTerm(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_TermApplCstTerm(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_TermConstantCstTerm(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a CstTerm", trm), IllegalArgument: true})
	}
	return results[0]
}

// CstTermFromString is Java Gom's CstTerm.fromString(s).
func CstTermFromString(s string) CstTerm { return CstTermFromTerm(aterm.GetInstance().Parse(s)) }

// CstTermFromStream is Java Gom's CstTerm.fromStream(stream) (an IOException is
// the error).
func CstTermFromStream(stream io.Reader) (CstTerm, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return CstTermFromTerm(at), nil
}

