// ConcCstTermCstTermList is the term type of the variadic operator `ConcCstTerm(...)` of sort CstTermList
// (Java's abstract class ConcCstTerm): a maximally-shared cons cell (Java's
// ConsConcCstTerm: a head and a tail) or the empty list (Java's EmptyConcCstTerm).
type ConcCstTermCstTermList struct {
	head  CstTerm
	tail  CstTermList
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*ConcCstTermCstTermList) isCstTermList() {}

func (t *ConcCstTermCstTermList) Hash() uint32 { return t.hash }

func (t *ConcCstTermCstTermList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcCstTermCstTermList)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *ConcCstTermCstTermList) Duplicate() sharedobjects.Term {
	return &ConcCstTermCstTermList{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new CstTerm[]{}): a last tail
// that is not a list (of sort CstTermList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcCstTermCstTermList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur CstTermList = t
	for {
		c, ok := cur.(*ConcCstTermCstTermList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcCstTermCstTermList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a ConcCstTerm list is not a CstTerm", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *ConcCstTermCstTermList) ChildCount() int { return len(t.elements()) }

func (t *ConcCstTermCstTermList) ChildAt(i int) any { return t.elements()[i] }

func (t *ConcCstTermCstTermList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *ConcCstTermCstTermList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: ConcCstTermFromArray(children).
func (t *ConcCstTermCstTermList) SetChildren(children []any) any {
	args := make([]CstTerm, len(children))
	for i, c := range children {
		args[i] = c.(CstTerm)
	}
	return MakeConcCstTerm(args...)
}

func (t *ConcCstTermCstTermList) String() string {
	var b strings.Builder
	b.WriteString("ConcCstTerm(")
	var cur CstTermList = t
	for {
		c, ok := cur.(*ConcCstTermCstTermList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsConcCstTerm is Java Gom's ConsConcCstTerm.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsConcCstTerm(head CstTerm, tail CstTermList) CstTermList {
	proto := &ConcCstTermCstTermList{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsConcCstTerm"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*ConcCstTermCstTermList)
}

// realMakeEmptyConcCstTerm is Java Gom's EmptyConcCstTerm.realMake: the shared empty list,
// without hook.
func realMakeEmptyConcCstTerm() CstTermList {
	proto := &ConcCstTermCstTermList{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyConcCstTerm"), nil)}
	return factory.Build(proto).(*ConcCstTermCstTermList)
}

// RawConcCstTerm builds the ConcCstTerm list holding exactly args, without construction
// hook.
func RawConcCstTerm(args ...CstTerm) CstTermList {
	l := realMakeEmptyConcCstTerm()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsConcCstTerm(args[i], l)
	}
	return l
}

// EmptyConcCstTerm is Java Gom's EmptyConcCstTerm.make(): the empty ConcCstTerm list, after the
// construction hooks.
func EmptyConcCstTerm() CstTermList {
	return realMakeEmptyConcCstTerm()
}

// ConsConcCstTerm is Java Gom's ConsConcCstTerm.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "" first).
func ConsConcCstTerm(head CstTerm, tail CstTermList) CstTermList {
	return RealMakeConsConcCstTerm(head, tail)
}

// MakeConcCstTerm builds the list of args as Tom's `ConcCstTerm(args…)` does: from EmptyConcCstTerm,
// by ConsConcCstTerm, through the construction hooks (Java's ConcCstTerm.fromArray).
func MakeConcCstTerm(args ...CstTerm) CstTermList {
	var l CstTermList = EmptyConcCstTerm()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsConcCstTerm(args[i], l)
	}
	return l
}

// ConcCstTermFromArray is Java Gom's ConcCstTerm.fromArray(array).
func ConcCstTermFromArray(array []CstTerm) CstTermList { return MakeConcCstTerm(array...) }

