// CstTypeFromTermConv is Java Gom's CstType.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func CstTypeFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) CstType {
	converted := conv.Convert(trm)
	var results []CstType
	if r, ok := fromTermCst_TypeCstType(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_TypeUnknownCstType(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a CstType", trm), IllegalArgument: true})
	}
	return results[0]
}

