// CstSymbolListFromTermConv is Java Gom's CstSymbolList.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func CstSymbolListFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) CstSymbolList {
	converted := conv.Convert(trm)
	var results []CstSymbolList
	if r, ok := fromTermConcCstSymbolCstSymbolList(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a CstSymbolList", trm), IllegalArgument: true})
	}
	return results[0]
}

