func (t *ConcCstSymbolCstSymbolList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcCstSymbolCstSymbolList)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *ConcCstSymbolCstSymbolList) Duplicate() sharedobjects.Term {
	return &ConcCstSymbolCstSymbolList{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new CstSymbol[]{}): a last tail
// that is not a list (of sort CstSymbolList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcCstSymbolCstSymbolList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur CstSymbolList = t
	for {
		c, ok := cur.(*ConcCstSymbolCstSymbolList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcCstSymbolCstSymbolList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a ConcCstSymbol list is not a CstSymbol", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *ConcCstSymbolCstSymbolList) ChildCount() int { return len(t.elements()) }

func (t *ConcCstSymbolCstSymbolList) ChildAt(i int) any { return t.elements()[i] }

func (t *ConcCstSymbolCstSymbolList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *ConcCstSymbolCstSymbolList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: ConcCstSymbolFromArray(children).
func (t *ConcCstSymbolCstSymbolList) SetChildren(children []any) any {
	args := make([]CstSymbol, len(children))
	for i, c := range children {
		args[i] = c.(CstSymbol)
	}
	return MakeConcCstSymbol(args...)
}

func (t *ConcCstSymbolCstSymbolList) String() string {
	var b strings.Builder
	b.WriteString("ConcCstSymbol(")
	var cur CstSymbolList = t
	for {
		c, ok := cur.(*ConcCstSymbolCstSymbolList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsConcCstSymbol is Java Gom's ConsConcCstSymbol.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsConcCstSymbol(head CstSymbol, tail CstSymbolList) CstSymbolList {
	proto := &ConcCstSymbolCstSymbolList{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsConcCstSymbol"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*ConcCstSymbolCstSymbolList)
}

// realMakeEmptyConcCstSymbol is Java Gom's EmptyConcCstSymbol.realMake: the shared empty list,
// without hook.
func realMakeEmptyConcCstSymbol() CstSymbolList {
	proto := &ConcCstSymbolCstSymbolList{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyConcCstSymbol"), nil)}
	return factory.Build(proto).(*ConcCstSymbolCstSymbolList)
}

// RawConcCstSymbol builds the ConcCstSymbol list holding exactly args, without construction
// hook.
func RawConcCstSymbol(args ...CstSymbol) CstSymbolList {
	l := realMakeEmptyConcCstSymbol()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsConcCstSymbol(args[i], l)
	}
	return l
}

