	var cur CstSymbolList = t
	var rev CstSymbolList = EmptyConcCstSymbol()
	for {
		c, ok := cur.(*ConcCstSymbolCstSymbolList)
		if !ok || c.empty {
			break
		}
		rev = ConsConcCstSymbol(c.head, rev)
		cur = c.tail
	}
	return rev
