// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcCstSymbolCstSymbolList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []CstSymbol
	var cur CstSymbolList = t
	for {
		c, ok := cur.(*ConcCstSymbolCstSymbolList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcCstSymbolCstSymbolList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcCstSymbolCstSymbolList is Java Gom's ConcCstSymbol.fromTerm: an application of ConcCstSymbol, or a
// list (of ToATerm), of convertible elements.
func fromTermConcCstSymbolCstSymbolList(trm aterm.ATerm, conv aterm.ATermConverter) (res CstSymbolList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "ConcCstSymbol" {
		elems := make([]CstSymbol, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = CstSymbolFromTermConv(a, conv)
		}
		return MakeConcCstSymbol(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a ConcCstSymbol (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []CstSymbol
		for !list.IsEmpty() {
			elems = append(elems, CstSymbolFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcCstSymbol(elems...), true
	}
	return nil, false
}

