// CstSymbolFromTerm is Java Gom's CstSymbol.fromTerm(trm).
func CstSymbolFromTerm(trm aterm.ATerm) CstSymbol {
	return CstSymbolFromTermConv(trm, aterm.IdConverter{})
}

// CstSymbolFromTermConv is Java Gom's CstSymbol.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func CstSymbolFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) CstSymbol {
	converted := conv.Convert(trm)
	var results []CstSymbol
	if r, ok := fromTermCst_SymbolCstSymbol(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_SymbolIntCstSymbol(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_SymbolLongCstSymbol(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_SymbolCharCstSymbol(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_SymbolDoubleCstSymbol(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_SymbolStringCstSymbol(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a CstSymbol", trm), IllegalArgument: true})
	}
	return results[0]
}

