// CstTheoryFromStream is Java Gom's CstTheory.fromStream(stream) (an IOException is
// the error).
func CstTheoryFromStream(stream io.Reader) (CstTheory, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return CstTheoryFromTerm(at), nil
}

