// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new CstPattern[]{}): a last tail
// that is not a list (of sort CstPatternList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcCstPatternCstPatternList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur CstPatternList = t
	for {
		c, ok := cur.(*ConcCstPatternCstPatternList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcCstPatternCstPatternList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a ConcCstPattern list is not a CstPattern", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

