func (t *ConcCstPatternCstPatternList) SetChildren(children []any) any {
	args := make([]CstPattern, len(children))
	for i, c := range children {
		args[i] = c.(CstPattern)
	}
	return MakeConcCstPattern(args...)
}

func (t *ConcCstPatternCstPatternList) String() string {
	var b strings.Builder
	b.WriteString("ConcCstPattern(")
	var cur CstPatternList = t
	for {
		c, ok := cur.(*ConcCstPatternCstPatternList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

