	if c, ok := cur.(*ConcCstOperatorCstOperatorList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a ConcCstOperator list is not a CstOperator", cur)})
	}
	c := t.ToArray()
