// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcCstOperatorCstOperatorList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []CstOperator
	var cur CstOperatorList = t
	for {
		c, ok := cur.(*ConcCstOperatorCstOperatorList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcCstOperatorCstOperatorList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcCstOperatorCstOperatorList is Java Gom's ConcCstOperator.fromTerm: an application of ConcCstOperator, or a
// list (of ToATerm), of convertible elements.
func fromTermConcCstOperatorCstOperatorList(trm aterm.ATerm, conv aterm.ATermConverter) (res CstOperatorList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "ConcCstOperator" {
		elems := make([]CstOperator, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = CstOperatorFromTermConv(a, conv)
		}
		return MakeConcCstOperator(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a ConcCstOperator (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []CstOperator
		for !list.IsEmpty() {
			elems = append(elems, CstOperatorFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcCstOperator(elems...), true
	}
	return nil, false
}

