	var cur CstSlotList = t
	for {
		c, ok := cur.(*ConcCstSlotCstSlotList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcCstSlotCstSlotList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a ConcCstSlot list is not a CstSlot", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
