// Length is Java's length(): the number of elements of the list (a
// tail that is not a ConcCstSlot list counts as one element).
func (t *ConcCstSlotCstSlotList) Length() int {
	res := 0
	var tl CstSlotList = t
	for {
		c, ok := tl.(*ConcCstSlotCstSlotList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*ConcCstSlotCstSlotList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a ConcCstSlot list.
func (t *ConcCstSlotCstSlotList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur CstSlotList = t
	for {
		c, ok := cur.(*ConcCstSlotCstSlotList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*ConcCstSlotCstSlotList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsConcCstSlot
// (through the hooks).
func (t *ConcCstSlotCstSlotList) Reverse() CstSlotList {
	if t.empty {
		return t
	}
	var cur CstSlotList = t
	var rev CstSlotList = EmptyConcCstSlot()
	for {
		c, ok := cur.(*ConcCstSlotCstSlotList)
		if !ok || c.empty {
			break
		}
		rev = ConsConcCstSlot(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsConcCstSlot (through the hooks).
func (t *ConcCstSlotCstSlotList) Append(element CstSlot) CstSlotList {
	var heads []CstSlot
	var cur CstSlotList = t
	for {
		c, ok := cur.(*ConcCstSlotCstSlotList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res CstSlotList
	if c, ok := cur.(*ConcCstSlotCstSlotList); ok && c.empty {
		res = ConsConcCstSlot(element, cur)
	} else {
		res = ConsConcCstSlot(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcCstSlot(heads[i], res)
	}
	return res
}

func (t *ConcCstSlotCstSlotList) CompareTo(o any) int {
	for {
		ao := o.(CstSlotList)
		if ao == CstSlotList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcCstSlotCstSlotList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcCstSlotCstSlotList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

