// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcCstSlotCstSlotList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []CstSlot
	var cur CstSlotList = t
	for {
		c, ok := cur.(*ConcCstSlotCstSlotList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcCstSlotCstSlotList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcCstSlotCstSlotList is Java Gom's ConcCstSlot.fromTerm: an application of ConcCstSlot, or a
// list (of ToATerm), of convertible elements.
func fromTermConcCstSlotCstSlotList(trm aterm.ATerm, conv aterm.ATermConverter) (res CstSlotList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "ConcCstSlot" {
		elems := make([]CstSlot, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = CstSlotFromTermConv(a, conv)
		}
		return MakeConcCstSlot(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a ConcCstSlot (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []CstSlot
		for !list.IsEmpty() {
			elems = append(elems, CstSlotFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcCstSlot(elems...), true
	}
	return nil, false
}

