// CstBQTermFromTermConv is Java Gom's CstBQTerm.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func CstBQTermFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) CstBQTerm {
	converted := conv.Convert(trm)
	var results []CstBQTerm
	if r, ok := fromTermCst_BQApplCstBQTerm(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_BQRecordApplCstBQTerm(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_BQVarCstBQTerm(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_BQVarStarCstBQTerm(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_BQDefaultCstBQTerm(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_BQCompositeCstBQTerm(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_ITLCstBQTerm(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_BQConstantCstBQTerm(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermCst_BQUnderscoreCstBQTerm(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a CstBQTerm", trm), IllegalArgument: true})
	}
	return results[0]
}

