func (t *Cst_BQApplCstBQTerm) CompareTo(o any) int {
	ao := o.(CstBQTerm)
	if ao == CstBQTerm(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*Cst_BQApplCstBQTerm)
	if c := t.OptionList.CompareTo(tco.OptionList); c != 0 {
		return c
	}
	if c := strings.Compare(t.Name, tco.Name); c != 0 {
		return c
	}
	if c := t.BqTermList.CompareTo(tco.BqTermList); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

