	var cur CstNameList = t
	for {
		c, ok := cur.(*ConcCstNameCstNameList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcCstNameCstNameList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a ConcCstName list is not a CstName", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
