func (t *ConcCstNameCstNameList) String() string {
	var b strings.Builder
	b.WriteString("ConcCstName(")
	var cur CstNameList = t
	for {
		c, ok := cur.(*ConcCstNameCstNameList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

