func (t *ConcCstOptionCstOptionList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcCstOptionCstOptionList)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

