// MakeConcCstOption builds the list of args as Tom's `ConcCstOption(args…)` does: from EmptyConcCstOption,
// by ConsConcCstOption, through the construction hooks (Java's ConcCstOption.fromArray).
func MakeConcCstOption(args ...CstOption) CstOptionList {
	var l CstOptionList = EmptyConcCstOption()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsConcCstOption(args[i], l)
	}
	return l
}

// ConcCstOptionFromArray is Java Gom's ConcCstOption.fromArray(array).
func ConcCstOptionFromArray(array []CstOption) CstOptionList { return MakeConcCstOption(array...) }

