// Append is Java's append(element): the list with element added at its
// end, built by ConsConcCstOption (through the hooks).
func (t *ConcCstOptionCstOptionList) Append(element CstOption) CstOptionList {
	var heads []CstOption
	var cur CstOptionList = t
	for {
		c, ok := cur.(*ConcCstOptionCstOptionList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res CstOptionList
	if c, ok := cur.(*ConcCstOptionCstOptionList); ok && c.empty {
		res = ConsConcCstOption(element, cur)
	} else {
		res = ConsConcCstOption(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcCstOption(heads[i], res)
	}
	return res
}

func (t *ConcCstOptionCstOptionList) CompareTo(o any) int {
	for {
		ao := o.(CstOptionList)
		if ao == CstOptionList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcCstOptionCstOptionList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcCstOptionCstOptionList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *ConcCstOptionCstOptionList) CompareToLPO(o any) int {
	for {
		ao := o.(CstOptionList)
		if ao == CstOptionList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcCstOptionCstOptionList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcCstOptionCstOptionList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcCstOptionCstOptionList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []CstOption
	var cur CstOptionList = t
	for {
		c, ok := cur.(*ConcCstOptionCstOptionList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcCstOptionCstOptionList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcCstOptionCstOptionList is Java Gom's ConcCstOption.fromTerm: an application of ConcCstOption, or a
// list (of ToATerm), of convertible elements.
func fromTermConcCstOptionCstOptionList(trm aterm.ATerm, conv aterm.ATermConverter) (res CstOptionList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "ConcCstOption" {
		elems := make([]CstOption, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = CstOptionFromTermConv(a, conv)
		}
		return MakeConcCstOption(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a ConcCstOption (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []CstOption
		for !list.IsEmpty() {
			elems = append(elems, CstOptionFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcCstOption(elems...), true
	}
	return nil, false
}

