// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new CstVisit[]{}): a last tail
// that is not a list (of sort CstVisitList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcCstVisitCstVisitList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur CstVisitList = t
	for {
		c, ok := cur.(*ConcCstVisitCstVisitList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcCstVisitCstVisitList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a ConcCstVisit list is not a CstVisit", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

